def calc(ts,new):
 b=n=h=hn=0
 for name,nb,ne in ts:
  head=(name=='token_embd.weight' and h==0) or name=='output.weight'
  if new:
   if head: h=nb*8/ne;hn=ne
   elif name.endswith('.weight'): b+=nb*8;n+=ne
  else:
   if any(name.endswith('.'+s+'.weight') for s in ['ffn_down','ffn_gate','ffn_up','attn_q','attn_k','attn_v','attn_output']): b+=nb*8;n+=ne
   if head: h=nb*8/ne;hn=ne
 return (b/n,h,hn*h+b)
a=[('token_embd.weight',200,100),('output.weight',200,100),('blk.0.attn_q.weight',100,100),('blk.0.ffn_up_exps.weight',100,200)]
print('synthetic old/new',calc(a,False),calc(a,True))
print('output before embedding',calc([a[1],a[0]]+a[2:],True))

